<?php
declare(strict_types=1);
namespace App\Repositories;
use PDO; use RuntimeException; use Throwable;
final class FinanceRepository{
 public function __construct(private PDO $db){}
 private function id(string $table,string $code):int{$allowed=['estados_orden_pago','estados_cuota','estados_pago','origenes_pago','medios_pago','estados_aplicacion_pago','tipos_linea_orden_pago','tipos_movimiento_kardex','estados_habilitacion_financiera','estados_habilitacion_matricula'];if(!in_array($table,$allowed,true))throw new RuntimeException('Catálogo financiero inválido.');$s=$this->db->prepare("SELECT id FROM {$table} WHERE codigo=:c AND activo=1 LIMIT 1");$s->execute(['c'=>$code]);$id=(int)$s->fetchColumn();if(!$id)throw new RuntimeException("No existe {$table}.{$code}.");return$id;}
 public function dashboard():array{return['orders'=>(int)$this->db->query("SELECT COUNT(*) FROM ordenes_pago o JOIN estados_orden_pago eo ON eo.id=o.estado_orden_pago_id WHERE eo.codigo<>'ANULADA'")->fetchColumn(),'pending'=>(int)$this->db->query("SELECT COUNT(*) FROM pagos p JOIN estados_pago e ON e.id=p.estado_pago_id WHERE e.codigo='PENDIENTE'")->fetchColumn(),'enabled'=>(int)$this->db->query("SELECT COUNT(*) FROM habilitaciones_financieras h JOIN estados_habilitacion_financiera e ON e.id=h.estado_habilitacion_financiera_id WHERE e.habilita_matricula=1 AND (h.fecha_hasta IS NULL OR h.fecha_hasta>=NOW())")->fetchColumn()];}
 public function tariffs():array{return$this->db->query("SELECT t.*,c.nombre carrera,m.codigo malla_codigo,m.nombre malla,n.nombre nivel,p.numero_version,pa.codigo periodo_codigo,pa.nombre periodo_nombre,tp.codigo_fuente tarifario_codigo FROM tarifas_academicas t JOIN carreras c ON c.id=t.carrera_id JOIN mallas_curriculares m ON m.id=t.malla_id JOIN niveles_academicos n ON n.id=t.nivel_academico_id JOIN politica_financiera_versiones p ON p.id=t.politica_financiera_version_id LEFT JOIN periodos_academicos pa ON pa.id=t.periodo_academico_id LEFT JOIN tarifarios_publicados tp ON tp.id=t.tarifario_publicado_id WHERE t.activo=1 ORDER BY pa.fecha_inicio DESC,c.nombre,m.codigo,n.orden_nivel,t.vigente_desde DESC")->fetchAll();}
 public function catalog():array{return['careers'=>$this->db->query("SELECT id,nombre FROM carreras WHERE activo=1 AND deleted_at IS NULL ORDER BY nombre")->fetchAll(),'curricula'=>$this->db->query("SELECT id,carrera_id,codigo,nombre FROM mallas_curriculares WHERE activo=1 AND deleted_at IS NULL ORDER BY codigo")->fetchAll(),'levels'=>$this->db->query("SELECT id,nombre,orden_nivel FROM niveles_academicos WHERE activo=1 ORDER BY orden_nivel")->fetchAll(),'policies'=>$this->db->query("SELECT v.id,p.nombre,v.numero_version,v.vigente_desde,v.vigente_hasta,v.cuotas_ordinarias,v.cuotas_ultimo_nivel FROM politica_financiera_versiones v JOIN politicas_financieras p ON p.id=v.politica_financiera_id WHERE v.vigente_desde<=CURDATE() AND (v.vigente_hasta IS NULL OR v.vigente_hasta>=CURDATE()) ORDER BY v.vigente_desde DESC")->fetchAll(),'periods'=>$this->db->query("SELECT id,codigo,nombre,fecha_inicio,fecha_fin FROM periodos_academicos WHERE activo=1 AND deleted_at IS NULL ORDER BY fecha_inicio DESC")->fetchAll(),'calendars'=>$this->db->query("SELECT cp.*,pa.codigo periodo_codigo,pa.nombre periodo_nombre FROM calendarios_pago_pao cp JOIN periodos_academicos pa ON pa.id=cp.periodo_academico_id WHERE cp.activo=1 ORDER BY pa.fecha_inicio DESC")->fetchAll()];}
 public function publishedTariffs():array{try{return$this->db->query("SELECT tp.nombre_programa,tp.malla_codigo_sugerida,tp.estado_vinculacion,COUNT(tn.id) niveles,tp.fuente_url FROM tarifarios_publicados tp LEFT JOIN tarifario_publicado_niveles tn ON tn.tarifario_publicado_id=tp.id GROUP BY tp.id ORDER BY tp.nombre_programa")->fetchAll();}catch(Throwable$e){return[];}}
 public function saveTariff(array$d,int$actor):void{$q=$this->db->prepare("SELECT carrera_id FROM mallas_curriculares WHERE id=:m");$q->execute(['m'=>$d['malla']]);if((int)$q->fetchColumn()!==$d['carrera'])throw new RuntimeException('La malla no pertenece a la carrera.');$pa=$this->db->prepare("SELECT fecha_inicio,fecha_fin FROM periodos_academicos WHERE id=:id AND activo=1 AND deleted_at IS NULL");$pa->execute(['id'=>$d['periodo']]);$period=$pa->fetch();if(!$period)throw new RuntimeException('El período académico seleccionado no existe o está inactivo.');if($d['desde']>$d['hasta'])throw new RuntimeException('La vigencia de la tarifa es inválida.');$dup=$this->db->prepare("SELECT id FROM tarifas_academicas WHERE periodo_academico_id=:pa AND carrera_id=:c AND malla_id=:m AND nivel_academico_id=:n AND activo=1 LIMIT 1");$dup->execute(['pa'=>$d['periodo'],'c'=>$d['carrera'],'m'=>$d['malla'],'n'=>$d['nivel']]);if($dup->fetchColumn())throw new RuntimeException('Ya existe una tarifa activa para este PAO, carrera, malla y nivel. Para conservar el histórico no se reemplaza automáticamente.');$s=$this->db->prepare("INSERT INTO tarifas_academicas(periodo_academico_id,carrera_id,malla_id,nivel_academico_id,politica_financiera_version_id,creditos_totales_nivel,valor_credito,arancel_base,valor_matricula,total_nivel_oficial,numero_cuotas,vigente_desde,vigente_hasta,es_ultimo_nivel,aprobado_por_usuario_id,activo) VALUES(:pa,:c,:m,:n,:p,:cr,:vc,:a,:vm,:tot,:nc,:vd,:vh,:ul,:u,1)");$s->execute(['pa'=>$d['periodo'],'c'=>$d['carrera'],'m'=>$d['malla'],'n'=>$d['nivel'],'p'=>$d['politica'],'cr'=>$d['creditos'],'vc'=>$d['valor_credito'],'a'=>$d['arancel'],'vm'=>$d['matricula'],'tot'=>$d['total_nivel'],'nc'=>$d['cuotas'],'vd'=>$d['desde'],'vh'=>$d['hasta']?:null,'ul'=>$d['ultimo'],'u'=>$actor?:null]);}
 public function savePaymentCalendar(array $d,int $actor):void{if(!$d['periodo']||!$d['primera_inicio']||!$d['primera_fin']||$d['primera_fin']<$d['primera_inicio']||$d['dia_inicio']<1||$d['dia_inicio']>28||$d['dia_fin']<$d['dia_inicio']||$d['dia_fin']>28)throw new RuntimeException('Calendario de pagos inválido. Los días recurrentes deben estar entre 1 y 28.');$q=$this->db->prepare("SELECT id FROM periodos_academicos WHERE id=:p AND activo=1 AND deleted_at IS NULL");$q->execute(['p'=>$d['periodo']]);if(!$q->fetchColumn())throw new RuntimeException('El PAO seleccionado no existe o está inactivo.');$s=$this->db->prepare("INSERT INTO calendarios_pago_pao(periodo_academico_id,primera_cuota_inicio,primera_cuota_fin,dia_inicio_recurrente,dia_fin_recurrente,actualizado_por_usuario_id,activo) VALUES(:p,:pi,:pf,:di,:df,:u,1) ON DUPLICATE KEY UPDATE primera_cuota_inicio=VALUES(primera_cuota_inicio),primera_cuota_fin=VALUES(primera_cuota_fin),dia_inicio_recurrente=VALUES(dia_inicio_recurrente),dia_fin_recurrente=VALUES(dia_fin_recurrente),actualizado_por_usuario_id=VALUES(actualizado_por_usuario_id),activo=1");$s->execute(['p'=>$d['periodo'],'pi'=>$d['primera_inicio'],'pf'=>$d['primera_fin'],'di'=>$d['dia_inicio'],'df'=>$d['dia_fin'],'u'=>$actor?:null]);}
 public function candidates(string$q=''):array{$sql="SELECT m.id matricula_id,m.numero_matricula,m.estudiante_carrera_id,m.periodo_academico_id,ec.carrera_id,ec.malla_id,ec.nivel_referencial_id,p.codigo_estudiante,pe.numero_identificacion,CONCAT_WS(' ',pe.primer_nombre,pe.segundo_nombre,pe.primer_apellido,pe.segundo_apellido) estudiante,c.nombre carrera,mc.codigo malla,na.nombre nivel,pa.nombre periodo,em.nombre estado,(SELECT op.id FROM ordenes_pago op JOIN estados_orden_pago eop ON eop.id=op.estado_orden_pago_id WHERE op.estudiante_carrera_id=m.estudiante_carrera_id AND op.periodo_academico_id=m.periodo_academico_id AND eop.codigo<>'ANULADA' ORDER BY op.id DESC LIMIT 1) orden_id FROM matriculas m JOIN estudiante_carreras ec ON ec.id=m.estudiante_carrera_id JOIN estudiantes p ON p.id=ec.estudiante_id JOIN personas pe ON pe.id=p.persona_id JOIN carreras c ON c.id=ec.carrera_id JOIN mallas_curriculares mc ON mc.id=ec.malla_id LEFT JOIN niveles_academicos na ON na.id=ec.nivel_referencial_id JOIN periodos_academicos pa ON pa.id=m.periodo_academico_id JOIN estados_matricula em ON em.id=m.estado_matricula_id WHERE em.codigo IN('BORRADOR','PENDIENTE_VALIDACION','PENDIENTE_FINANCIERO')";$args=[];if(trim($q)!==''){$sql.=" AND (pe.numero_identificacion LIKE :q1 OR p.codigo_estudiante LIKE :q2 OR CONCAT_WS(' ',pe.primer_nombre,pe.segundo_nombre,pe.primer_apellido,pe.segundo_apellido) LIKE :q3)";$like='%'.trim($q).'%';$args=['q1'=>$like,'q2'=>$like,'q3'=>$like];}$sql.=" ORDER BY m.id DESC LIMIT 100";$s=$this->db->prepare($sql);$s->execute($args);return$s->fetchAll();}
 private function currentTariff(array $m):array{$s=$this->db->prepare("SELECT t.*,v.porcentaje_abono_habilita,pa.fecha_inicio,pa.fecha_fin,cp.primera_cuota_inicio,cp.primera_cuota_fin,cp.dia_inicio_recurrente,cp.dia_fin_recurrente,tp.codigo_fuente tarifario_codigo FROM tarifas_academicas t JOIN politica_financiera_versiones v ON v.id=t.politica_financiera_version_id JOIN periodos_academicos pa ON pa.id=t.periodo_academico_id LEFT JOIN calendarios_pago_pao cp ON cp.periodo_academico_id=pa.id AND cp.activo=1 LEFT JOIN tarifarios_publicados tp ON tp.id=t.tarifario_publicado_id WHERE t.periodo_academico_id=:periodo AND t.carrera_id=:c AND t.malla_id=:ma AND t.nivel_academico_id=:n AND t.activo=1 AND t.valor_credito IS NOT NULL AND t.total_nivel_oficial IS NOT NULL AND ABS(t.total_nivel_oficial-(t.arancel_base+t.valor_matricula))<=0.02 ORDER BY t.vigente_desde DESC LIMIT 1");$s->execute(['periodo'=>$m['periodo_academico_id'],'c'=>$m['carrera_id'],'ma'=>$m['malla_id'],'n'=>$m['nivel_referencial_id']]);$r=$s->fetch();if(!$r)throw new RuntimeException('No existe un tarifario oficial completo para este PAO, carrera, malla y nivel.');if(empty($r['primera_cuota_inicio'])||empty($r['primera_cuota_fin']))throw new RuntimeException('El PAO tiene tarifario, pero todavía no tiene calendario de pagos. Configure la primera ventana y los días recurrentes antes de generar la orden.');return$r;}
 public function createOrderFromEnrollment(int$matricula,int$actor):int{$s=$this->db->prepare("SELECT m.*,ec.carrera_id,ec.malla_id,ec.nivel_referencial_id FROM matriculas m JOIN estudiante_carreras ec ON ec.id=m.estudiante_carrera_id WHERE m.id=:id");$s->execute(['id'=>$matricula]);$m=$s->fetch();if(!$m)throw new RuntimeException('Matrícula no encontrada.');if(!$m['nivel_referencial_id'])throw new RuntimeException('La trayectoria no tiene nivel referencial.');$x=$this->db->prepare("SELECT o.id FROM ordenes_pago o JOIN estados_orden_pago eo ON eo.id=o.estado_orden_pago_id WHERE o.estudiante_carrera_id=:e AND o.periodo_academico_id=:p AND eo.codigo<>'ANULADA' LIMIT 1");$x->execute(['e'=>$m['estudiante_carrera_id'],'p'=>$m['periodo_academico_id']]);if($id=(int)$x->fetchColumn())return$id;$t=$this->currentTariff($m);$other=$this->db->prepare("SELECT COALESCE(SUM(monto),0) FROM tarifa_conceptos_adicionales WHERE tarifa_academica_id=:t AND obligatorio=1");$other->execute(['t'=>$t['id']]);$otros=(float)$other->fetchColumn();$baseOfficial=round((float)$t['total_nivel_oficial'],2);$total=round($baseOfficial+$otros,2);if($total<=0)throw new RuntimeException('La tarifa vigente genera un total de pago igual a cero.');$this->db->beginTransaction();try{$num='OP-'.date('Ymd').'-'.$m['estudiante_carrera_id'].'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);$st=$this->id('estados_orden_pago','GENERADA');$i=$this->db->prepare("INSERT INTO ordenes_pago(numero_orden,estudiante_carrera_id,periodo_academico_id,nivel_academico_id,tarifa_academica_id,estado_orden_pago_id,generada_por_tipo,generada_por_usuario_id,fecha_vencimiento,subtotal_arancel,subtotal_matricula,subtotal_otros,total_descuentos,total_becas,total_pagar,saldo_pendiente,snapshot_creditos,snapshot_valor_credito,snapshot_arancel_oficial,snapshot_matricula,snapshot_total_oficial,snapshot_numero_cuotas,snapshot_tarifario_codigo,observacion) VALUES(:no,:ec,:p,:n,:t,:s,'ACADEMICO',:u,:fv,:a,:ma,:o,0,0,:to,:saldo,:scr,:svc,:sa,:sm,:sto,:snc,:stc,'Generada desde matrícula inicial Orion')");$i->execute(['no'=>$num,'ec'=>$m['estudiante_carrera_id'],'p'=>$m['periodo_academico_id'],'n'=>$m['nivel_referencial_id'],'t'=>$t['id'],'s'=>$st,'u'=>$actor?:null,'fv'=>$t['primera_cuota_fin'],'a'=>$t['arancel_base'],'ma'=>$t['valor_matricula'],'o'=>$otros,'to'=>$total,'saldo'=>$total,'scr'=>$t['creditos_totales_nivel'],'svc'=>$t['valor_credito'],'sa'=>$t['arancel_base'],'sm'=>$t['valor_matricula'],'sto'=>$t['total_nivel_oficial'],'snc'=>$t['numero_cuotas'],'stc'=>$t['tarifario_codigo']??null]);$oid=(int)$this->db->lastInsertId();$this->detail($oid,'ARANCEL','Arancel base',(float)$t['arancel_base']);$this->detail($oid,'MATRICULA','Matrícula',(float)$t['valor_matricula']);if($otros>0)$this->detail($oid,'OTRO_CARGO','Conceptos adicionales obligatorios',$otros);$count=(int)$t['numero_cuotas'];$base=floor(($total/$count)*100)/100;$acc=0;$cs=$this->id('estados_cuota','PENDIENTE');$firstStart=new \DateTimeImmutable($t['primera_cuota_inicio']);$firstEnd=new \DateTimeImmutable($t['primera_cuota_fin']);for($n=1;$n<=$count;$n++){$amount=$n===$count?round($total-$acc,2):$base;$acc+=$amount;if($n===1){$start=$firstStart;$end=$firstEnd;}else{$month=$firstStart->modify('first day of this month')->modify('+'.($n-1).' month');$start=$month->setDate((int)$month->format('Y'),(int)$month->format('m'),(int)$t['dia_inicio_recurrente']);$end=$month->setDate((int)$month->format('Y'),(int)$month->format('m'),(int)$t['dia_fin_recurrente']);}$c=$this->db->prepare("INSERT INTO cuotas_pago(orden_pago_id,estado_cuota_id,numero_cuota,fecha_inicio_pago,fecha_fin_pago,monto_cuota,saldo_cuota) VALUES(:o,:e,:n,:fi,:ff,:monto,:saldo)");$c->execute(['o'=>$oid,'e'=>$cs,'n'=>$n,'fi'=>$start->format('Y-m-d'),'ff'=>$end->format('Y-m-d'),'monto'=>$amount,'saldo'=>$amount]);}$this->db->commit();return$oid;}catch(Throwable$e){$this->db->rollBack();throw$e;}}
 private function detail(int$o,string$type,string$desc,float$amount):void{if($amount<=0)return;$s=$this->db->prepare("INSERT INTO orden_pago_detalles(orden_pago_id,tipo_linea_id,descripcion,cantidad,valor_unitario,monto_total,orden_visual) VALUES(:o,:t,:d,1,:vu,:mt,1)");$s->execute(['o'=>$o,'t'=>$this->id('tipos_linea_orden_pago',$type),'d'=>$desc,'vu'=>$amount,'mt'=>$amount]);}
 public function order(int$id):?array{$s=$this->db->prepare("SELECT o.*,eo.codigo estado_codigo,eo.nombre estado,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) estudiante,e.codigo_estudiante,c.nombre carrera,m.codigo malla,n.nombre nivel,pa.nombre periodo,pa.codigo periodo_codigo,COALESCE(o.snapshot_creditos,ta.creditos_totales_nivel) creditos_totales_nivel,COALESCE(o.snapshot_valor_credito,ta.valor_credito) valor_credito,COALESCE(o.snapshot_arancel_oficial,ta.arancel_base) tarifa_arancel,COALESCE(o.snapshot_matricula,ta.valor_matricula) tarifa_matricula,COALESCE(o.snapshot_total_oficial,ta.total_nivel_oficial) total_nivel_oficial,COALESCE(o.snapshot_numero_cuotas,ta.numero_cuotas) tarifa_cuotas,ta.vigente_desde tarifa_desde,ta.vigente_hasta tarifa_hasta,tp.codigo_fuente tarifario_codigo,tp.periodo_nombre tarifario_periodo,tp.fuente_url tarifario_fuente FROM ordenes_pago o JOIN estados_orden_pago eo ON eo.id=o.estado_orden_pago_id JOIN estudiante_carreras ec ON ec.id=o.estudiante_carrera_id JOIN estudiantes e ON e.id=ec.estudiante_id JOIN personas p ON p.id=e.persona_id JOIN carreras c ON c.id=ec.carrera_id JOIN mallas_curriculares m ON m.id=ec.malla_id JOIN niveles_academicos n ON n.id=o.nivel_academico_id JOIN periodos_academicos pa ON pa.id=o.periodo_academico_id JOIN tarifas_academicas ta ON ta.id=o.tarifa_academica_id LEFT JOIN tarifarios_publicados tp ON tp.id=ta.tarifario_publicado_id WHERE o.id=:id");$s->execute(['id'=>$id]);return$s->fetch()?:null;}
 public function installments(int$id):array{$s=$this->db->prepare("SELECT c.*,e.codigo estado_codigo,e.nombre estado FROM cuotas_pago c JOIN estados_cuota e ON e.id=c.estado_cuota_id WHERE c.orden_pago_id=:o ORDER BY c.numero_cuota");$s->execute(['o'=>$id]);return$s->fetchAll();}
 public function payments(int$id):array{$s=$this->db->prepare("SELECT p.*,a.id comprobante_disponible,e.codigo estado_codigo,e.nombre estado,c.numero_cuota,me.nombre medio,dist.distribucion FROM pagos p LEFT JOIN archivos a ON a.id=p.comprobante_archivo_id JOIN estados_pago e ON e.id=p.estado_pago_id LEFT JOIN cuotas_pago c ON c.id=p.cuota_pago_id LEFT JOIN medios_pago me ON me.id=p.medio_pago_id LEFT JOIN (SELECT a.pago_id,GROUP_CONCAT(CONCAT('Cuota ',cu.numero_cuota,': $',FORMAT(a.monto_aplicado,2)) ORDER BY cu.numero_cuota SEPARATOR ' · ') distribucion FROM aplicaciones_pago a JOIN cuotas_pago cu ON cu.id=a.cuota_pago_id GROUP BY a.pago_id) dist ON dist.pago_id=p.id WHERE p.orden_pago_id=:o ORDER BY p.id DESC");$s->execute(['o'=>$id]);return$s->fetchAll();}
 public function paymentCatalog():array{return['media'=>$this->db->query("SELECT id,codigo,nombre FROM medios_pago WHERE activo=1 ORDER BY nombre")->fetchAll()];}
 public function registerPayment(int$order,int$cuota,float$amount,string$date,int$medium,int$fileId,string$ref,int$actor):int{$o=$this->order($order);if(!$o)throw new RuntimeException('Orden no encontrada.');if($o['estado_codigo']==='ANULADA')throw new RuntimeException('Orden anulada.');if(!is_finite($amount)||$amount<=0||round($amount,2)!=$amount)throw new RuntimeException('Monto de pago inválido.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Fecha inválida.');$q=$this->db->prepare("SELECT id,fecha_inicio_pago,fecha_fin_pago FROM cuotas_pago WHERE id=:c AND orden_pago_id=:o");$q->execute(['c'=>$cuota,'o'=>$order]);$c=$q->fetch();if(!$c)throw new RuntimeException('La cuota no pertenece a la orden.');$outside=($date<$c['fecha_inicio_pago']||$date>$c['fecha_fin_pago'])?1:0;$num='PG-'.date('Ymd').'-'.str_pad((string)random_int(1,99999999),8,'0',STR_PAD_LEFT);$s=$this->db->prepare("INSERT INTO pagos(numero_pago,estudiante_carrera_id,orden_pago_id,cuota_pago_id,estado_pago_id,origen_pago_id,medio_pago_id,monto_reportado,fecha_pago,comprobante_archivo_id,referencia_bancaria,registrado_por_usuario_id,registrado_fuera_ventana,registrado_por_financiero,observacion) VALUES(:n,:ec,:o,:c,:e,:or,:me,:m,:f,:a,:r,:u,:fv,1,'Registrado por Financiero')");$s->execute(['n'=>$num,'ec'=>$o['estudiante_carrera_id'],'o'=>$order,'c'=>$cuota,'e'=>$this->id('estados_pago','PENDIENTE'),'or'=>$this->id('origenes_pago','FINANCIERO'),'me'=>$medium?:null,'m'=>$amount,'f'=>$date,'a'=>$fileId,'r'=>$ref?:null,'u'=>$actor,'fv'=>$outside]);return(int)$this->db->lastInsertId();}
 public function pendingPayments():array{return$this->db->query("SELECT p.id,p.numero_pago,p.monto_reportado,p.fecha_pago,p.orden_pago_id,c.numero_cuota,CONCAT_WS(' ',pe.primer_nombre,pe.segundo_nombre,pe.primer_apellido,pe.segundo_apellido) estudiante FROM pagos p JOIN estados_pago e ON e.id=p.estado_pago_id JOIN cuotas_pago c ON c.id=p.cuota_pago_id JOIN estudiantes es ON es.id=(SELECT ec.estudiante_id FROM estudiante_carreras ec WHERE ec.id=p.estudiante_carrera_id) JOIN personas pe ON pe.id=es.persona_id WHERE e.codigo='PENDIENTE' ORDER BY p.fecha_registro")->fetchAll();}
 public function reviewPayment(int $payment,string $decision,string $obs,int $actor):void{
  if(!in_array($decision,['APROBAR','RECHAZADO'],true))throw new RuntimeException('Decisión de revisión inválida.');
  $this->db->beginTransaction();
  try{
   $s=$this->db->prepare("SELECT p.*,eo.codigo orden_estado FROM pagos p JOIN ordenes_pago o ON o.id=p.orden_pago_id JOIN estados_orden_pago eo ON eo.id=o.estado_orden_pago_id WHERE p.id=:id FOR UPDATE");
   $s->execute(['id'=>$payment]);$p=$s->fetch();if(!$p)throw new RuntimeException('Pago no encontrado.');
   if($p['orden_estado']==='ANULADA')throw new RuntimeException('No se pueden revisar pagos de una orden anulada.');
   $cur=$this->db->prepare('SELECT codigo FROM estados_pago WHERE id=:id');$cur->execute(['id'=>$p['estado_pago_id']]);
   if($cur->fetchColumn()!=='PENDIENTE')throw new RuntimeException('El comprobante ya fue revisado.');
   if($decision==='RECHAZADO'){
    if($obs==='')throw new RuntimeException('La observación es obligatoria al rechazar.');
    $st=$this->db->prepare('UPDATE pagos SET estado_pago_id=:e,revisado_por_usuario_id=:u,fecha_revision=NOW(),motivo_rechazo=:m,observacion=:ob WHERE id=:id');
    $st->execute(['e'=>$this->id('estados_pago','RECHAZADO'),'u'=>$actor,'m'=>$obs,'ob'=>$obs,'id'=>$payment]);
    $this->db->commit();return;
   }
   // Bloquea la orden y todas las cuotas para serializar aprobaciones concurrentes.
   $lock=$this->db->prepare('SELECT id,saldo_pendiente,estudiante_carrera_id,periodo_academico_id,tarifa_academica_id FROM ordenes_pago WHERE id=:id FOR UPDATE');
   $lock->execute(['id'=>$p['orden_pago_id']]);$o=$lock->fetch();
   $cs=$this->db->prepare('SELECT id,numero_cuota,monto_cuota,monto_pagado_aprobado FROM cuotas_pago WHERE orden_pago_id=:id ORDER BY numero_cuota FOR UPDATE');
   $cs->execute(['id'=>$p['orden_pago_id']]);$cuotas=$cs->fetchAll();
   $remaining=(int)round((float)$p['monto_reportado']*100);
   $saldo=(int)round((float)$o['saldo_pendiente']*100);
   if($remaining<=0)throw new RuntimeException('Monto inválido.');
   if($remaining>$saldo)throw new RuntimeException('El pago supera el saldo total de la orden. El saldo a favor requiere un proceso separado.');
   $app=$this->db->prepare("INSERT INTO aplicaciones_pago(pago_id,cuota_pago_id,estado_aplicacion_id,monto_aplicado,aplicado_por_usuario_id,observacion) VALUES(:p,:c,:e,:m,:u,'Distribución automática por orden cronológico')");
   $up=$this->db->prepare('UPDATE cuotas_pago SET estado_cuota_id=:e,monto_pagado_aprobado=:mp,saldo_cuota=:saldo,porcentaje_pagado=:pct,habilita_plataformas=:h,fecha_pago_completo=:fecha WHERE id=:id');
   $first=null;$firstApplied=0;$partial=false;
   foreach($cuotas as $c){
    $original=(int)round((float)$c['monto_cuota']*100);$paid=(int)round((float)$c['monto_pagado_aprobado']*100);
    $apply=min($remaining,max(0,$original-$paid));if($apply>0){
     $new=$paid+$apply;$full=$new >= $original;$pct=$original>0?round($new*100/$original,2):100;
     $app->execute(['p'=>$payment,'c'=>$c['id'],'e'=>$this->id('estados_aplicacion_pago','APLICADA'),'m'=>number_format($apply/100,2,'.',''),'u'=>$actor]);
     $up->execute(['e'=>$this->id('estados_cuota',$full?'PAGADA':'ABONO'),'mp'=>number_format($new/100,2,'.',''),'saldo'=>number_format(($original-$new)/100,2,'.',''),'pct'=>$pct,'h'=>$pct>=80?1:0,'fecha'=>$full?date('Y-m-d H:i:s'):null,'id'=>$c['id']]);
     $remaining-=$apply;if(!$full)$partial=true;
    }else{$new=$paid;}
    if((int)$c['numero_cuota']===1){$first=['id'=>(int)$c['id'],'original'=>$original,'paid'=>$new];if($apply>0)$firstApplied=1;}
   }
   if($remaining!==0)throw new RuntimeException('No se pudo distribuir completamente el pago.');
   if($partial&&$obs==='')throw new RuntimeException('La observación es obligatoria cuando existe un abono parcial.');
   $status=$partial?'ABONO':'APROBADO';
   $upPayment=$this->db->prepare('UPDATE pagos SET estado_pago_id=:e,revisado_por_usuario_id=:u,fecha_revision=NOW(),observacion=:ob WHERE id=:id');
   $upPayment->execute(['e'=>$this->id('estados_pago',$status),'u'=>$actor,'ob'=>$obs?:null,'id'=>$payment]);
   $upd=$this->db->prepare('UPDATE ordenes_pago SET saldo_pendiente=:saldo WHERE id=:id');
   $upd->execute(['saldo'=>number_format(($saldo-(int)round((float)$p['monto_reportado']*100))/100,2,'.',''),'id'=>$o['id']]);
   // La habilitación depende de la primera cuota acumulada, nunca de la última cuota pagada.
   if($first&&$firstApplied){
    $threshold=$this->db->prepare('SELECT v.porcentaje_abono_habilita FROM tarifas_academicas t JOIN politica_financiera_versiones v ON v.id=t.politica_financiera_version_id WHERE t.id=:id');
    $threshold->execute(['id'=>$o['tarifa_academica_id']]);$th=(float)$threshold->fetchColumn();
    $pct=$first['original']>0?$first['paid']*100/$first['original']:100;
    $code=$first['paid']>=$first['original']?'HABILITADA':($pct+0.00001 >= $th?'HABILITADA_ABONO_80':'BLOQUEADA_MENOR_80');
    $this->syncEnablement((int)$o['estudiante_carrera_id'],(int)$o['periodo_academico_id'],$first['id'],$payment,$code,'Primera cuota acumulada: '.number_format($pct,2).'%',$actor);
   }
   $this->db->commit();
   // La revisión financiera ya fue confirmada. La transición académica se ejecuta
   // después del commit para no anidar transacciones PDO independientes.
   // Si falla, el pago sigue aprobado y puede recuperarse con el conciliador CLI.
   if ($first && $firstApplied && in_array($code ?? '', ['HABILITADA', 'HABILITADA_ABONO_80'], true)) {
    try {
     $this->confirmEnabledEnrollments((int)$o['estudiante_carrera_id'], (int)$o['periodo_academico_id'], $actor);
    } catch (Throwable $syncError) {
     error_log('[Orion] Confirmación automática pendiente para trayectoria '.(int)$o['estudiante_carrera_id'].': '.$syncError->getMessage());
    }
   }
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
 }
 /** Confirma solamente matrículas pendientes con habilitación financiera vigente. */
 public function confirmEnabledEnrollments(int $trajectory, int $period, int $actor): int {
  $q=$this->db->prepare("SELECT h.id FROM habilitaciones_financieras h JOIN estados_habilitacion_financiera e ON e.id=h.estado_habilitacion_financiera_id WHERE h.estudiante_carrera_id=:t AND h.periodo_academico_id=:p AND e.habilita_matricula=1 AND (h.fecha_hasta IS NULL OR h.fecha_hasta>=NOW()) LIMIT 1");
  $q->execute(['t'=>$trajectory,'p'=>$period]);
  if(!$q->fetchColumn())return 0;
  // La confirmación individual abre su propia transacción y valida de nuevo el estado.
  $q=$this->db->prepare("SELECT m.id FROM matriculas m JOIN estados_matricula e ON e.id=m.estado_matricula_id WHERE m.estudiante_carrera_id=:t AND m.periodo_academico_id=:p AND m.activo=1 AND e.codigo='PENDIENTE_FINANCIERO' ORDER BY m.id");
  $q->execute(['t'=>$trajectory,'p'=>$period]);
  $ids=$q->fetchAll(PDO::FETCH_COLUMN);
  $academic=new AcademicEnrollmentRepository($this->db);
  $confirmed=0;
  foreach($ids as $id){
   try{if($academic->academicConfirm((int)$id,$actor)==='CONFIRMADA')$confirmed++;}
   catch(RuntimeException $e){
    // Si otra operación ya confirmó esta matrícula, el reintento es inocuo.
    $state=$this->db->prepare("SELECT e.codigo FROM matriculas m JOIN estados_matricula e ON e.id=m.estado_matricula_id WHERE m.id=:id");
    $state->execute(['id'=>$id]);
    if($state->fetchColumn()!=='CONFIRMADA')throw $e;
   }
  }
  return $confirmed;
 }
 public function annulOrder(int $orderId,string $reason,int $actor):void{if(trim($reason)==='')throw new RuntimeException('Debes indicar el motivo de anulación.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT o.id,eo.codigo estado_codigo,(SELECT COUNT(*) FROM pagos p WHERE p.orden_pago_id=o.id) pagos FROM ordenes_pago o JOIN estados_orden_pago eo ON eo.id=o.estado_orden_pago_id WHERE o.id=:id FOR UPDATE");$q->execute(['id'=>$orderId]);$o=$q->fetch();if(!$o)throw new RuntimeException('Orden no encontrada.');if($o['estado_codigo']==='ANULADA'){ $this->db->commit(); return; }if((int)$o['pagos']>0)throw new RuntimeException('No se puede anular una orden que ya tiene pagos registrados.');$an=$this->id('estados_orden_pago','ANULADA');$u=$this->db->prepare("UPDATE ordenes_pago SET estado_orden_pago_id=:e,anulada_at=NOW(),anulada_por_usuario_id=:u,motivo_anulacion=:m,observacion=CONCAT(COALESCE(observacion,''),'\nANULADA: ',:m2) WHERE id=:id");$u->execute(['e'=>$an,'u'=>$actor?:null,'m'=>trim($reason),'m2'=>trim($reason),'id'=>$orderId]);$ca=$this->id('estados_cuota','ANULADA');$c=$this->db->prepare("UPDATE cuotas_pago SET estado_cuota_id=:e WHERE orden_pago_id=:o");$c->execute(['e'=>$ca,'o'=>$orderId]);$this->db->commit();}catch(Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 private function syncEnablement(int$ec,int$period,?int$cuota,?int$pago,string$finCode,string$reason,int$actor):void{$fin=$this->id('estados_habilitacion_financiera',$finCode);$s=$this->db->prepare("INSERT INTO habilitaciones_financieras(estudiante_carrera_id,periodo_academico_id,estado_habilitacion_financiera_id,cuota_referencia_id,pago_referencia_id,fecha_desde,motivo,actualizado_por_usuario_id) VALUES(:e,:p,:s,:c,:pg,NOW(),:m,:u) ON DUPLICATE KEY UPDATE estado_habilitacion_financiera_id=VALUES(estado_habilitacion_financiera_id),cuota_referencia_id=VALUES(cuota_referencia_id),pago_referencia_id=VALUES(pago_referencia_id),fecha_desde=NOW(),fecha_hasta=NULL,motivo=VALUES(motivo),actualizado_por_usuario_id=VALUES(actualizado_por_usuario_id)");$s->execute(['e'=>$ec,'p'=>$period,'s'=>$fin,'c'=>$cuota,'pg'=>$pago,'m'=>$reason,'u'=>$actor]);$enabled=in_array($finCode,['HABILITADA','HABILITADA_ABONO_80'],true);$acad=$this->id('estados_habilitacion_matricula',$enabled?'HABILITADA':'BLOQUEADA_FINANCIERO');$h=$this->db->prepare("INSERT INTO habilitaciones_matricula(estudiante_carrera_id,periodo_academico_id,estado_habilitacion_id,origen,referencia_id,fecha_habilitacion,fecha_deshabilitacion,observacion) VALUES(:e,:p,:s,'FINANCIERO',:r,:fh,:fd,:o) ON DUPLICATE KEY UPDATE estado_habilitacion_id=VALUES(estado_habilitacion_id),origen='FINANCIERO',referencia_id=VALUES(referencia_id),fecha_habilitacion=VALUES(fecha_habilitacion),fecha_deshabilitacion=VALUES(fecha_deshabilitacion),observacion=VALUES(observacion)");$h->execute(['e'=>$ec,'p'=>$period,'s'=>$acad,'r'=>$pago,'fh'=>$enabled?date('Y-m-d H:i:s'):null,'fd'=>$enabled?null:date('Y-m-d H:i:s'),'o'=>$reason]);}
}
